//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns whether this error is eligible for another attempt.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

#[cfg(test)]
mod tests {
    use super::RetryError;

    #[test]
    fn only_transient_errors_are_retryable() {
        assert!(RetryError::Transient("temporary".into()).is_transient());
        assert!(!RetryError::Permanent("invalid input".into()).is_transient());
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay for a retry after `retry_index` previous retries.
    pub(crate) fn delay_for_retry(&self, retry_index: u32) -> u64 {
        let mut delay = self.base_delay_ms.min(self.max_delay_ms);

        // A u64 delay can double at most 64 times before reaching its cap.
        for _ in 0..retry_index.min(u64::BITS) {
            delay = delay.saturating_mul(2).min(self.max_delay_ms);
            if delay == self.max_delay_ms {
                break;
            }
        }

        delay
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn delay_saturates_without_overflowing() {
        let config = RetryConfig {
            max_attempts: u32::MAX,
            base_delay_ms: u64::MAX,
            max_delay_ms: u64::MAX,
        };

        assert_eq!(config.delay_for_retry(u32::MAX), u64::MAX);
    }

    #[test]
    fn huge_retry_index_reaches_a_small_cap_without_overflowing() {
        let config = RetryConfig {
            max_attempts: u32::MAX,
            base_delay_ms: 1,
            max_delay_ms: u64::MAX,
        };

        assert_eq!(config.delay_for_retry(u32::MAX), u64::MAX);
    }

    #[test]
    fn delay_is_capped_at_each_step() {
        let config = RetryConfig {
            max_attempts: 5,
            base_delay_ms: 3,
            max_delay_ms: 10,
        };

        assert_eq!(config.delay_for_retry(0), 3);
        assert_eq!(config.delay_for_retry(1), 6);
        assert_eq!(config.delay_for_retry(2), 10);
        assert_eq!(config.delay_for_retry(100), 10);
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let mut attempts = 0;

    loop {
        attempts += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if error.is_transient() && attempts < config.max_attempts => {
                sleeper.sleep_ms(config.delay_for_retry(attempts - 1));
            }
            Err(error) => return Err(error),
        }
    }
}

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

fn transient(message: &str) -> RetryError {
    RetryError::Transient(message.to_owned())
}

#[test]
fn retries_transient_errors_with_bounded_exponential_delays() {
    let config = RetryConfig {
        max_attempts: 4,
        base_delay_ms: 10,
        max_delay_ms: 25,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        if calls < 4 {
            Err(transient("temporary outage"))
        } else {
            Ok(())
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 4);
    assert_eq!(sleeper.sleeps, vec![10, 20, 25]);
}

#[test]
fn max_attempts_includes_first_call_when_transient_errors_exhaust_budget() {
    let config = RetryConfig {
        max_attempts: 3,
        base_delay_ms: 1,
        max_delay_ms: 100,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(transient("still unavailable"))
    });

    assert_eq!(result, Err(transient("still unavailable")));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![1, 2]);
}

#[test]
fn permanent_errors_return_without_retrying() {
    let config = RetryConfig {
        max_attempts: 5,
        base_delay_ms: 10,
        max_delay_ms: 100,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("invalid job".to_owned()))
    });

    assert_eq!(result, Err(RetryError::Permanent("invalid job".to_owned())));
    assert_eq!(calls, 1);
}

#[test]
fn public_run_job_saturates_delays_past_u64_exponent_range() {
    let config = RetryConfig {
        max_attempts: 67,
        base_delay_ms: 1,
        max_delay_ms: u64::MAX,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        if calls < 67 {
            Err(transient("still unavailable"))
        } else {
            Ok(())
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 67);
    assert_eq!(sleeper.sleeps.len(), 66);
    assert_eq!(sleeper.sleeps[64..], [u64::MAX, u64::MAX]);
}
